def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]

    for i in range(len(s) - len(prefix) - len(suffix) + 2):
        if s.startswith(prefix, i):
            # Check that suffix is found after the prefix
            suffix_start_index = i + len(prefix)
            if suffix and s.find(suffix, suffix_start_index) != -1:
                return True
            elif not suffix:  # Handle the case where suffix is empty
                return True
    return False

