def countPartitions(nums: List[int]) -> int:
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return 0
    left_sum = 0
    count = 0
    for i in range(len(nums) - 1):
        left_sum += nums[i]
        right_sum = total_sum - left_sum
        if (left_sum - right_sum) % 2 == 0:
            count += 1
    return count

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if counts[s[i]] == first_digit and counts[s[i + 1]] == second_digit:
                return s[i] + s[i + 1]
    return ""

