def sumOfGoodNumbers(nums: List[int], k: int) -> int:
    total_sum = 0
    n = len(nums)
    for i in range(n):
        is_good = True
        if i - k >= 0:
            is_good = is_good and nums[i] > nums[i - k]
        if i + k < n:
            is_good = is_good and nums[i] > nums[i + k]
        if is_good:
            total_sum += nums[i]
    return total_sum

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == 1:
            left_neighbor = s[i - 1] if i > 0 else None
            right_neighbor = s[i + k] if i + k < n else None
            if (left_neighbor is None or left_neighbor != substring[0]) and (right_neighbor is None or right_neighbor != substring[0]):
                return True
    return False

def hasSameDigits(s: str) -> bool:
    while len(s) > 2:
        s = ''.join(str((int(s[i]) + int(s[i + 1])) % 10) for i in range(len(s) - 1))
    return s[0] == s[1]

