def maxSum(nums: List[int]) -> int:
    unique_elements = set()
    current_sum = 0
    max_sum = float('-inf')

    for num in nums:
        if num not in unique_elements:
            unique_elements.add(num)
            current_sum += num
        else:
            max_sum = max(max_sum, current_sum)
            # Reset for the next unique sequence
            unique_elements.clear()
            unique_elements.add(num)
            current_sum = num

    # Final check for the last sequence
    max_sum = max(max_sum, current_sum)

    if max_sum == float('-inf'):
        return max(nums)
    return max(max_sum, 0)

def maxContainers(n: int, w: int, maxWeight: int) -> int:
    max_containers_by_deck = n * n
    max_containers_by_weight = maxWeight // w
    return min(max_containers_by_deck, max_containers_by_weight)

def reverseDegree(s: str) -> int:
    total = 0
    for index, char in enumerate(s):
        position_in_reversed_alphabet = 26 - (ord(char) - ord('a'))
        total += position_in_reversed_alphabet * (index + 1)
    return total

