def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    # Group events by timestamp
    events_by_timestamp = {}
    for event in events:
        timestamp = int(event[1])
        if timestamp not in events_by_timestamp:
            events_by_timestamp[timestamp] = []
        events_by_timestamp[timestamp].append(event)

    # Process events in chronological order
    for timestamp in sorted(events_by_timestamp.keys()):
        for event in events_by_timestamp[timestamp]:
            event_type, _, data = event

            # Process offline events
            if event_type == "OFFLINE":
                user_id = int(data)
                online_status[user_id] = False
                offline_until[user_id] = timestamp + 60

        # Update online status for all users before processing messages
        for user_id in range(numberOfUsers):
            if not online_status[user_id] and timestamp >= offline_until[user_id]:
                online_status[user_id] = True

        # Process message events
        for event in events_by_timestamp[timestamp]:
            if event[0] == "MESSAGE":
                mentions_string = event[2].split()
                for mention in mentions_string:
                    if mention.startswith("id"):
                        user_id = int(mention[2:])
                        mentions[user_id] += 1
                    elif mention == "ALL":
                        for user_id in range(numberOfUsers):
                            mentions[user_id] += 1
                    elif mention == "HERE":
                        for user_id in range(numberOfUsers):
                            if online_status[user_id]:
                                mentions[user_id] += 1

    return mentions
